    async def update_person(
        self,
        person_reference: str,
        *,
        first_name: typing.Optional[str] = OMIT,
        middle_name: typing.Optional[str] = OMIT,
        last_name: typing.Optional[str] = OMIT,
        primary_email: typing.Optional[str] = OMIT,
        secondary_email: typing.Optional[str] = OMIT,
        primary_phone_number: typing.Optional[str] = OMIT,
        secondary_phone_number: typing.Optional[str] = OMIT,
        nationality: typing.Optional[str] = OMIT,
        national_id_issuer: typing.Optional[str] = OMIT,
        drivers_license_number: typing.Optional[str] = OMIT,
        drivers_license_state: typing.Optional[str] = OMIT,
        external_id: typing.Optional[str] = OMIT,
        custom_data: typing.Optional[typing.Dict[str, typing.Any]] = OMIT,
        addresses: typing.Optional[typing.Sequence[PersonAddressRequest]] = OMIT,
        identification_documents: typing.Optional[typing.Sequence[IdentificationDocumentRequest]] = OMIT,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> PersonUpdatedEnvelope:
        """
        Applies a partial update to a person. Send only the fields you want to change.

        A person's job title belongs to their business link, not the person. Sending `title` in any form, including `null`, returns a `400` with the message `title moved to the business relationship; update it with PATCH /api/v2/businesses/{businessReference}/people/{personReference}.`

        Parameters
        ----------
        person_reference : str
            The person reference.

        first_name : typing.Optional[str]
            The person's first name.

        middle_name : typing.Optional[str]
            The person's middle name.

        last_name : typing.Optional[str]
            The person's last name.

        primary_email : typing.Optional[str]
            The person's primary email address.

        secondary_email : typing.Optional[str]
            The person's secondary email address.

        primary_phone_number : typing.Optional[str]
            The person's primary phone number.

        secondary_phone_number : typing.Optional[str]
            The person's secondary phone number.

        nationality : typing.Optional[str]
            The person's nationality, as a two-letter ISO 3166-1 alpha-2 country code. Nationality selects which identity number applies — `US` uses `ssn`, and any other value uses `nationalIdNumber` and `nationalIdIssuer`.

        national_id_issuer : typing.Optional[str]
            The authority that issued the national ID, used when `nationality` is not `US`.

        drivers_license_number : typing.Optional[str]
            The person's driver's license number.

        drivers_license_state : typing.Optional[str]
            The two-letter state code for the driver's license.

        external_id : typing.Optional[str]
            Your own identifier for the person.

        custom_data : typing.Optional[typing.Dict[str, typing.Any]]
            Key-value data to merge into the person's stored `customData`.
            Payabli stores an owner's answers to a boarding template's
            custom questions under the `templateAnswers` key.

            When you update a person, Payabli merges `customData` into the
            stored value, following JSON Merge Patch (RFC 7396). Keys you
            don't send are kept at every depth, and nested objects merge key
            by key. Strings, numbers, Boolean values, and arrays replace the
            stored value, and arrays aren't merged. Send a key as `null` to
            delete it, such as `{"crmId": null}`. A `customData` that isn't
            an object, such as an array, replaces the stored value whole.
            Leave out `customData` to keep it as is.

            The `customData` you send can be up to 65,536 bytes serialized.
            The limit applies to the request, not to the merged result.

        addresses : typing.Optional[typing.Sequence[PersonAddressRequest]]
            Postal addresses associated with the person.

        identification_documents : typing.Optional[typing.Sequence[IdentificationDocumentRequest]]
            Government-issued identification documents for the person.

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        PersonUpdatedEnvelope
            Person updated.

        Examples
        --------
        import asyncio

        from payabli import Asyncpayabli

        client = Asyncpayabli(
            client_id="YOUR_CLIENT_ID",
            client_secret="YOUR_CLIENT_SECRET",
        )


        async def main() -> None:
            await client.people.update_person(
                person_reference="01a0014d-ce1a-7110-9bac-c4c59647a88d",
                primary_phone_number="3055550199",
            )


        asyncio.run(main())
        """
        _response = await self._raw_client.update_person(
            person_reference,
            first_name=first_name,
            middle_name=middle_name,
            last_name=last_name,
            primary_email=primary_email,
            secondary_email=secondary_email,
            primary_phone_number=primary_phone_number,
            secondary_phone_number=secondary_phone_number,
            nationality=nationality,
            national_id_issuer=national_id_issuer,
            drivers_license_number=drivers_license_number,
            drivers_license_state=drivers_license_state,
            external_id=external_id,
            custom_data=custom_data,
            addresses=addresses,
            identification_documents=identification_documents,
            request_options=request_options,
        )
        return _response.data

